for part in ['B','C']:
    rows=[]
    path=ROOT/f'{part}.tex'
    s=path.read_text()
    for ident,claim,status,deps,sec,folio,scans,reading,notes in DATA:
        if not ident.startswith(part+'.'):
            continue
        passage=f'LM §{sec}; folio {folio}; scan {scans}'
        rows.append([ident,claim,status,f'sections/{part}.tex, {ident}',deps,passage,reading,notes])
        key='\\label{'+ident.replace('.','')+'}\n'
        marker=f'\\textit{{Manuscript: LM \\S{sec}, folio {folio}, scans {scans}.}}\n'
        if key in s and marker not in s[s.index(key):s.index(key)+len(key)+len(marker)+3]:
            s=s.replace(key,key+marker,1)
    path.write_text(s)
    with (ROOT/f'{part}_results.csv').open('w',newline='') as f:
        w=csv.writer(f);w.writerow(FIELDS);w.writerows(rows)
    print(f'{part}: wrote {len(rows)} statement rows and manuscript coordinates.')

